@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#121c29;--navy:#192737;--panel:#1d2c3c;--panel2:#223447;--line:#35485a;--text:#e9e9df;--muted:#91a0ad;--gold:#e5b459;--blue:#61a9d8;--red:#d26d5d;--green:#73b783}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#0f1721;color:var(--text);font-family:'DM Sans',sans-serif;display:flex;align-items:center;justify-content:center;padding:20px;background-image:radial-gradient(ellipse at 50% 0%,#263c4f 0%,#131e2a 52%,#0d141e 100%)}button{font:inherit;color:inherit;cursor:pointer}.game-shell{width:min(1360px,100%);background:#172331;border:1px solid #354454;box-shadow:0 28px 90px #070b10aa;border-radius:10px;overflow:hidden}.topbar{height:58px;background:#1a2938;border-bottom:1px solid #334455;display:flex;align-items:center;justify-content:space-between;padding:0 22px}.brand{display:flex;align-items:center;gap:10px;color:#c5d0d5;font:800 15px 'Barlow Condensed',sans-serif;letter-spacing:1.6px;text-decoration:none}.brand b{color:#e8bc66}.brand-mark{width:29px;height:29px;background:#344354;color:#e8bc66;border:1px solid #536274;border-radius:6px;display:grid;place-items:center;font-size:17px}.mission{display:flex;align-items:center;gap:10px;color:#94a1aa;font-size:9px;font-weight:700;letter-spacing:1.3px}.mission b{color:#e8bc66}.mission i{height:14px;width:1px;background:#475563;margin:0 4px}.mission-dot,.log-pip{width:6px;height:6px;background:#d66b58;border-radius:50%;box-shadow:0 0 8px #d66b5888}.top-actions{display:flex;gap:8px}.icon-btn{width:31px;height:29px;border:1px solid #3c4c5a;background:#223344;border-radius:5px;color:#b1bec5}.icon-btn:hover{color:#f3c76f;border-color:#907746}.stage-wrap{position:relative;overflow:hidden;background:#4f6472}.stage-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:1280/600}.battle-vignette{position:absolute;inset:0;box-shadow:inset 0 20px 30px #17233155,inset 0 -45px 60px #10182288;pointer-events:none}.stage-hud{position:absolute;top:17px;left:22px;right:22px;display:grid;grid-template-columns:1fr auto 1fr;align-items:start;gap:18px}.base-card{width:238px;padding:10px 12px 9px;background:#172536d9;border:1px solid #5b778a99;border-radius:5px;box-shadow:0 6px 20px #111a2288}.red-base{justify-self:end;border-color:#a66b6299}.base-name{display:flex;align-items:center;gap:9px}.base-name>span:last-child{display:flex;flex-direction:column;gap:2px}.base-name b{font:700 12px 'Barlow Condensed',sans-serif;letter-spacing:1.2px}.base-name small{font-size:8px;color:#9eabb2;letter-spacing:1.2px}.shield-icon{color:#79b9dd;font-size:16px}.red-base .shield-icon{color:#df8470}.base-health{display:flex;align-items:center;gap:8px;margin-top:8px}.health-track{height:5px;background:#0d1720;border-radius:8px;flex:1;overflow:hidden}.health-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#65b0d7,#89c6e2);transition:width .25s}.red-base .health-track i{background:linear-gradient(90deg,#c7584c,#ed9372)}.base-health>b{font:600 10px 'Barlow Condensed',sans-serif;color:#c1cbd0;white-space:nowrap}.wave-card{margin-top:5px;text-align:center;padding:8px 15px;background:#172536cc;border:1px solid #60728266;border-radius:4px;display:flex;flex-direction:column;gap:3px;min-width:144px}.wave-card small{font-size:8px;color:#b2bec1;letter-spacing:1.3px}.wave-card b{font:800 16px 'Barlow Condensed',sans-serif;color:#edc16e;letter-spacing:1.4px}.wave-card span{font-size:8px;color:#c5ced0;letter-spacing:.6px}.battle-log{position:absolute;left:22px;bottom:15px;display:flex;align-items:center;gap:8px;background:#14202ccc;border:1px solid #57697970;padding:8px 11px;border-radius:4px;font-size:10px;color:#d6d8d0;max-width:60%;text-shadow:0 1px 3px #000}.battle-log .log-pip{background:#e5b459;box-shadow:none}.toast{position:absolute;left:50%;top:102px;transform:translateX(-50%) translateY(-8px);opacity:0;background:#1c2936ee;border:1px solid #e5b45988;color:#f0d192;padding:9px 16px;border-radius:4px;font-size:11px;font-weight:700;transition:.2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}.command-deck{min-height:158px;display:grid;grid-template-columns:140px minmax(140px,1fr) minmax(390px,2.4fr) minmax(220px,1.3fr);border-top:1px solid #394b5a;background:#1b2a39}.command-deck>div{padding:13px 15px;border-right:1px solid #364757}.command-deck>div:last-child{border:0}.economy{display:flex;align-items:center;gap:9px;position:relative}.gold-medallion{width:32px;height:32px;border-radius:50%;background:#463c2b;border:1px solid #8e7444;display:grid;place-items:center;color:#f0c66c;font-size:19px;box-shadow:0 0 15px #e3b5521a}.economy>div:nth-child(2){display:flex;flex-direction:column;gap:1px}.economy small,.training-title,.roster-title{font:700 9px 'Barlow Condensed',sans-serif;letter-spacing:1.3px;color:#9dabb3}.economy strong{font:800 23px 'Barlow Condensed',sans-serif;color:#f2ce7e;line-height:1}.income{position:absolute;bottom:13px;left:17px;color:#80bd91;font-size:9px;font-weight:600}.roster-title,.training-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.roster-title span,.training-title span{font:600 8px 'DM Sans',sans-serif;letter-spacing:.6px;color:#70828e}.roster-icons{display:flex;flex-wrap:wrap;gap:5px;align-content:start}.empty-roster{font-size:10px;color:#71818c;font-style:italic;padding-top:7px}.roster-unit{width:29px;height:30px;border-radius:4px;background:#263a4b;border:1px solid #405767;display:grid;place-items:center;color:#b7d7e5;font-size:15px;position:relative}.roster-unit.miner{color:#e3c179}.roster-unit.archer{color:#95c7aa}.roster-unit.giant{color:#dc9a80}.roster-unit.dead{opacity:.35}.train-buttons{display:grid;grid-template-columns:repeat(4,minmax(75px,1fr));gap:7px}.train-btn{position:relative;display:flex;align-items:center;gap:8px;padding:9px 8px;height:62px;text-align:left;background:#243648;border:1px solid #405667;border-radius:5px;transition:background .15s,border-color .15s,transform .15s}.train-btn:hover{background:#2c4255;border-color:#9c824e;transform:translateY(-1px)}.train-btn:active{transform:translateY(1px)}.train-btn.disabled{opacity:.47}.unit-symbol{font-size:21px;width:25px;text-align:center;color:#e8c876}.sword-symbol{color:#b6d2e1}.archer-symbol{color:#9bc5a7}.giant-symbol{color:#dfa084}.unit-info{display:flex;flex-direction:column;gap:3px;min-width:0}.unit-info b{font:700 10px 'Barlow Condensed',sans-serif;letter-spacing:.55px;white-space:nowrap}.unit-info small{font-size:8px;color:#9daab0;white-space:nowrap}.unit-cost{position:absolute;right:7px;bottom:5px;font:700 9px 'Barlow Condensed',sans-serif;color:#e8c578}.unit-cost i{font-style:normal;margin-right:3px}.train-btn kbd,.order-btn kbd{position:absolute;top:4px;right:5px;font:8px 'DM Sans',sans-serif;color:#80919b;background:#172635;padding:1px 4px;border-radius:2px}.orders .training-title{margin-bottom:12px}.order-buttons{display:flex;gap:6px}.order-btn{position:relative;flex:1;height:62px;background:#243648;border:1px solid #405667;border-radius:5px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:#a8b7be}.order-btn>span{font-size:18px;line-height:1}.order-btn b{font:700 9px 'Barlow Condensed',sans-serif;letter-spacing:.7px}.order-btn kbd{top:auto;bottom:4px;right:5px}.order-btn.active{background:#334653;border-color:#c49b58;color:#f0ca7a;box-shadow:inset 0 0 14px #dfb9580d}.order-btn:hover{border-color:#9d8050}footer{height:28px;background:#172432;border-top:1px solid #293c4b;padding:0 18px;display:flex;align-items:center;justify-content:space-between;color:#71828d;font:600 8px 'Barlow Condensed',sans-serif;letter-spacing:1.2px}footer i{font-style:normal;color:#dfb967;margin:0 4px}.pause-overlay,.result-overlay,.help-overlay{position:absolute;inset:0;background:#0c1620b8;backdrop-filter:blur(3px);display:grid;place-items:center;z-index:3}.hidden{display:none!important}.pause-panel,.result-panel,.help-panel{width:min(410px,90%);padding:30px 34px;background:#1a2938;border:1px solid #637281;border-radius:7px;box-shadow:0 15px 50px #070c12bb;text-align:center}.eyebrow{font:700 10px 'Barlow Condensed',sans-serif;letter-spacing:2px;color:#e2b95f}.pause-panel h2,.result-panel h2,.help-panel h2{margin:8px 0 7px;font:800 32px 'Barlow Condensed',sans-serif;color:#f2f0e5}.pause-panel p,.result-panel p,.help-panel p{margin:0 0 20px;font-size:12px;color:#a7b3b8;line-height:1.5}.primary-btn{border:1px solid #d6ad61;background:#bd9146;color:#111a22;border-radius:4px;padding:11px 16px;font:800 11px 'Barlow Condensed',sans-serif;letter-spacing:1.1px}.primary-btn:hover{background:#e3bb6d}.primary-btn span{padding-left:12px}.result-stats{display:flex;justify-content:center;gap:30px;margin:17px 0 22px}.result-stats span{display:flex;flex-direction:column;gap:4px;font:600 8px 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#8f9da4}.result-stats b{font:700 17px 'Barlow Condensed',sans-serif;color:#e8c373}.help-panel{position:relative;text-align:left;width:min(510px,92%)}.help-panel h2{margin-bottom:6px}.close-btn{position:absolute;right:14px;top:10px;background:none;border:0;color:#9faeb5;font-size:24px}.help-grid{display:grid;gap:10px;margin:16px 0 20px}.help-grid>div{display:flex;align-items:flex-start;gap:12px}.help-grid>div>b{background:#304659;border:1px solid #536a7b;border-radius:50%;width:22px;height:22px;display:grid;place-items:center;color:#e8c373;font:700 11px 'Barlow Condensed',sans-serif;flex:none}.help-grid>div>span{font-size:11px;color:#aab7bc;line-height:1.45}.help-grid strong{display:block;color:#e7e9e2;margin-bottom:2px}.help-panel kbd{padding:1px 5px;background:#34485a;border-radius:3px;color:#f2d18a;font-size:9px}.help-panel .primary-btn{width:100%}
@media(max-width:1000px){body{padding:0}.game-shell{border-radius:0}.command-deck{grid-template-columns:110px 1fr 2fr}.orders{grid-column:1/-1;border-top:1px solid #364757;display:flex;align-items:center;gap:18px}.orders .training-title{width:130px;margin:0}.order-buttons{flex:1}.order-btn{height:42px}.command-deck>div{padding:10px}.income{left:10px;bottom:8px}.stage-hud{left:12px;right:12px;top:10px}.base-card{width:205px;padding:8px}.wave-card{padding:6px}.battle-log{left:12px;bottom:9px}}@media(max-width:650px){body{padding:0}.topbar{height:48px;padding:0 12px}.mission{display:none}.stage-wrap canvas{aspect-ratio:900/600;object-fit:cover}.stage-hud{grid-template-columns:1fr auto 1fr;gap:4px}.base-card{width:auto;min-width:0;padding:7px}.base-name{gap:5px}.base-name b{font-size:9px}.base-name small{font-size:7px}.base-health>b{font-size:8px}.wave-card{min-width:75px;padding:5px 3px}.wave-card small{font-size:6px}.wave-card b{font-size:12px}.wave-card span{font-size:6px}.battle-log{font-size:8px;max-width:78%}.command-deck{grid-template-columns:100px 1fr}.command-deck>.training{grid-column:1/-1;border-top:1px solid #364757}.command-deck>.orders{grid-column:1/-1}.train-buttons{gap:5px}.train-btn{padding:7px 5px;height:55px;gap:4px}.unit-symbol{width:20px;font-size:17px}.unit-info b{font-size:9px}.unit-info small{font-size:7px}.unit-cost{right:4px;font-size:8px}.training-title{margin-bottom:8px}footer span:nth-child(2){display:none}}

(() => {
  'use strict';
  const canvas = document.getElementById('battlefield');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height, GROUND = 496;
  const ui = Object.fromEntries(['goldText','incomeText','playerHealthBar','playerHealthText','enemyHealthBar','enemyHealthText','waveText','waveStatus','armyCount','rosterIcons','logText','toast','pauseOverlay','resultOverlay','resultEyebrow','resultTitle','resultCopy','killsStat','timeStat'].map(id => [id, document.getElementById(id)]));
  const definitions = {
    miner: {name:'Miner',cost:100,hp:82,damage:0,range:0,speed:30,icon:'⛏',color:'#e4c378'},
    sword: {name:'Swordwrath',cost:150,hp:145,damage:22,range:19,speed:39,icon:'⚔',color:'#d7e2e4'},
    archer: {name:'Archidon',cost:225,hp:100,damage:18,range:250,speed:27,icon:'➶',color:'#a9d2b2'},
    giant: {name:'Giant',cost:400,hp:440,damage:62,range:24,speed:16,icon:'♟',color:'#dda083'}
  };
  let gold=250, playerHP=1000, enemyHP=1000, elapsed=0, kills=0, paused=false, finished=false, order='attack', enemySpawn=5, minerTick=0, enemyTick=0, wave=1, toastTimer=0, soundOn=false;
  let units=[], enemies=[], projectiles=[], particles=[], clouds=[], logTimer=0;
  let rng=987654321; const rand=()=>{rng=(rng*1664525+1013904223)>>>0;return rng/4294967296};
  for(let i=0;i<8;i++)clouds.push({x:rand()*W,y:38+rand()*150,w:50+rand()*105,s:.8+rand()*2,a:.1+rand()*.12});
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function log(message){ui.logText.textContent=message; logTimer=4.5}
  function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=1.6}
  function unitCount(){return units.filter(u=>u.hp>0).length}
  function train(type){if(finished||paused)return;const d=definitions[type];if(gold<d.cost){toast('NOT ENOUGH GOLD');return}if(unitCount()>=34){toast('YOUR ARMY IS FULL');return}gold-=d.cost;units.push({type,x:150+rand()*42,y:GROUND,hp:d.hp,maxHp:d.hp,attackCd:rand()*.5,walk:rand()*8,bob:rand()*8});log(`${d.name.toUpperCase()} JOINED THE ORDER.`);refreshUI()}
  function setOrder(next){if(finished)return;order=next;document.querySelectorAll('.order-btn').forEach(b=>b.classList.toggle('active',b.id===`${next}Btn`));const texts={attack:'ORDERS RECEIVED: ADVANCE AND DESTROY.',hold:'ORDERS RECEIVED: HOLD THIS GROUND.',retreat:'ORDERS RECEIVED: FALL BACK TO THE CITADEL.'};log(texts[next])}
  function pause(value=!paused){if(finished)return;paused=value;ui.pauseOverlay.classList.toggle('hidden',!paused)}
  function restart(){gold=250;playerHP=enemyHP=1000;elapsed=0;kills=0;paused=false;finished=false;order='attack';wave=1;enemySpawn=5;minerTick=enemyTick=0;units=[];enemies=[];projectiles=[];particles=[];ui.resultOverlay.classList.add('hidden');ui.pauseOverlay.classList.add('hidden');setOrder('attack');log('THE VALLEY IS YOURS TO COMMAND, GENERAL.');refreshUI()}
  function finish(win){finished=true;ui.resultEyebrow.textContent=win?'VICTORY':'DEFEAT';ui.resultTitle.textContent=win?'The valley is yours.':'The citadel has fallen.';ui.resultCopy.textContent=win?'The Order stands unbroken.':'The Chaos Legion has claimed the Iron Valley.';ui.killsStat.textContent=String(kills);ui.timeStat.textContent=formatTime(elapsed);ui.resultOverlay.classList.remove('hidden')}
  function formatTime(s){const n=Math.floor(s);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
  function refreshUI(){ui.goldText.textContent=Math.floor(gold);const miners=units.filter(u=>u.hp>0&&u.type==='miner').length;ui.incomeText.textContent=`+${miners*5} / sec`;ui.playerHealthBar.style.width=`${clamp(playerHP/10,0,100)}%`;ui.playerHealthText.textContent=`${Math.ceil(playerHP)} / 1000`;ui.enemyHealthBar.style.width=`${clamp(enemyHP/10,0,100)}%`;ui.enemyHealthText.textContent=`${Math.ceil(enemyHP)} / 1000`;const count=unitCount();ui.armyCount.textContent=`${count} ${count===1?'UNIT':'UNITS'}`;const live=units.filter(u=>u.hp>0);ui.rosterIcons.innerHTML=live.length?live.map(u=>`<span class="roster-unit ${u.type}" title="${definitions[u.type].name} · ${Math.ceil(u.hp)} HP">${definitions[u.type].icon}</span>`).join(''):'<span class="empty-roster">Train units to build your army</span>';ui.waveText.textContent=`WAVE ${String(wave).padStart(2,'0')}`;ui.waveStatus.textContent=finished?(enemyHP<=0?'LEGION DEFEATED':'CITADEL FALLEN'):elapsed<9?'SCOUTS APPROACHING':`THREATS: ${enemies.length}`;document.querySelectorAll('.train-btn').forEach(b=>b.classList.toggle('disabled',gold<definitions[b.dataset.unit].cost))}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(rand()-.5)*95,vy:-25-rand()*90,life:.35+rand()*.5,size:2+rand()*3,color})}
  function spawnEnemy(){const difficulty=1+Math.min(elapsed/145,.9);const type=elapsed>58&&rand()<.16?'giant':elapsed>21&&rand()<.4?'archer':'sword';const d=definitions[type];enemies.push({type,x:W-160-rand()*30,y:GROUND,hp:d.hp*difficulty,maxHp:d.hp*difficulty,damage:d.damage*(.8+Math.min(elapsed/250,.5)),range:d.range,attackCd:rand()*.6,walk:rand()*8,bob:rand()*8,speed:d.speed*(.76+rand()*.38)})}
  function update(dt){if(paused||finished)return;elapsed+=dt;minerTick+=dt;enemyTick+=dt;enemySpawn-=dt;logTimer=Math.max(0,logTimer-dt);toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');if(minerTick>=1){const miners=units.filter(u=>u.hp>0&&u.type==='miner').length;gold+=miners*5;minerTick%=1}if(enemySpawn<=0){spawnEnemy();enemySpawn=Math.max(2.5,8.5-elapsed*.035);if(elapsed>36&&Math.floor(elapsed/38)>=wave){wave++;log(`WAVE ${String(wave).padStart(2,'0')} — CHAOS REINFORCEMENTS INBOUND.`)}}
    const all=[...units.filter(u=>u.hp>0).map(u=>({...u,side:'player'})),...enemies.map(u=>({...u,side:'enemy'}))];
    for(const u of units){if(u.hp<=0)continue;u.attackCd-=dt;u.walk+=dt*6;const d=definitions[u.type];if(u.type==='miner'){u.x=112+Math.sin(elapsed*.48+u.bob)*31;continue}if(order==='retreat'){u.x=Math.max(110,u.x-d.speed*dt);continue}if(order==='hold'&&u.x<390){const target=enemies.find(e=>e.hp>0&&Math.abs(e.x-u.x)<(u.type==='archer'?d.range:160));if(target){if(u.type==='archer'){if(u.attackCd<=0){shoot(u,target,true);u.attackCd=1.25}}else if(Math.abs(target.x-u.x)<d.range+targetRadius(target)){hit(u,target,d.damage,true);u.attackCd=.82}}continue}
      const target=enemies.filter(e=>e.hp>0).sort((a,b)=>Math.abs(a.x-u.x)-Math.abs(b.x-u.x))[0];if(!target){if(u.type==='archer'&&u.x<720)u.x+=d.speed*dt*.55;else if(u.x<1000)u.x+=d.speed*dt;continue}const dist=Math.abs(target.x-u.x);if(u.type==='archer'){if(dist>d.range)u.x+=d.speed*dt;else if(u.attackCd<=0){shoot(u,target,true);u.attackCd=1.34+rand()*.3}}else if(dist>d.range+targetRadius(target)){u.x+=d.speed*dt}else if(u.attackCd<=0){hit(u,target,d.damage,true);u.attackCd=u.type==='giant'?1.4:.75}}
    for(const e of enemies){if(e.hp<=0)continue;e.attackCd-=dt;e.walk+=dt*5;const nearest=units.filter(u=>u.hp>0&&u.type!=='miner').sort((a,b)=>Math.abs(a.x-e.x)-Math.abs(b.x-e.x))[0];if(e.type==='archer'){const dist=nearest?Math.abs(e.x-nearest.x):Math.abs(e.x-112);if(nearest&&dist<e.range){if(e.attackCd<=0){shoot(e,nearest,false);e.attackCd=1.7}}else if(!nearest&&e.x>185){if(e.attackCd<=0){shoot(e,null,false);e.attackCd=1.7}}else if(nearest&&dist>=e.range)e.x-=e.speed*dt*.55;continue}const stop=nearest?targetRadius(nearest)+18:60;const dist=nearest?Math.abs(e.x-nearest.x):Math.abs(e.x-112);if(dist>stop)e.x-=e.speed*dt;else if(e.attackCd<=0){if(nearest){nearest.hp-=e.damage;if(nearest.hp<=0){burst(nearest.x,GROUND-18,'#dca17b',10);log(`${definitions[nearest.type].name.toUpperCase()} FALLEN IN BATTLE.`)}}else playerHP-=e.damage;e.attackCd=e.type==='giant'?1.8:1.05}}
    for(const p of projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=65*dt;p.life-=dt;if(p.life<=0)continue;if(p.friendly){const target=p.target;if(target&&target.hp>0&&Math.abs(target.x-p.x)<17&&Math.abs((GROUND-19)-p.y)<22){target.hp-=p.damage;p.life=0;burst(p.x,p.y,'#e1c17b',3)}}else if(p.target&&p.target.hp>0&&Math.abs(p.target.x-p.x)<17&&Math.abs((GROUND-19)-p.y)<22){p.target.hp-=p.damage;p.life=0;burst(p.x,p.y,'#df8a70',3)}else if(!p.target&&p.x<160){playerHP-=p.damage;p.life=0;burst(145,GROUND-25,'#d97563',4)}}
    projectiles=projectiles.filter(p=>p.life>0);for(const e of enemies){if(e.hp<=0){kills++;gold+=18;burst(e.x,GROUND-16,'#df8c70',7)}}enemies=enemies.filter(e=>e.hp>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=150*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(enemyHP<=0)finish(true);else if(playerHP<=0)finish(false);refreshUI()}
